tool_input.command:
$p = "D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh-experimental-session-search"
Write-Output "=== 包内文件 ==="; Get-ChildItem $p -ErrorAction SilentlyContinue | Select-Object Name
Write-Output "=== cordis.patch.yml ==="; if(Test-Path "$p\cordis.patch.yml"){ Get-Content "$p\cordis.patch.yml" -Raw } else { "no patch file" }

$web="$env:USERPROFILE\.dsh\profiles\web"; $bin="D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh\lib\bin.js"
Write-Output "=== dump-config: 抽 optional-tool-session-query / tool-workflow 结构 ==="
node $bin --profile web --dump-config 2>&1 | Select-String -Pattern "optional-tool-session-query|optional-session-search|tool-workflow|preset-standard|preset-full-tools" -Context 1,2 | Select-Object -First 40 | ForEach-Object { $_.Line }

$web="$env:USERPROFILE\.dsh\profiles\web"; $bin="D:\nvm\v22.23.2\node_modules\@deepseek-ai\dsh\lib\bin.js"
$out = node $bin --profile web --dump-config 2>&1
Write-Output "=== preset-full-tools 块内容(看是否含 session-query / workflow) ==="
$start = ($out | Select-String -Pattern "id: preset-full-tools" | Select-Object -First 1).LineNumber
if($start){
  $seg = $out[($start-3)..([Math]::Min($start+120,$out.Count-1))]
  $seg | Select-String -Pattern "order|session|optional|tool-workflow|tool-schedule|disabled" | ForEach-Object { $_.Line }
}
